const CACHE='stack-lab-assets-da010a1d2c900241';
const SHELL=['/','/gem-tools.js?v=da010a1d2c900241','/board-presets.js?v=da010a1d2c900241','/board-app.js?v=da010a1d2c900241','/board.css?v=da010a1d2c900241','/responsive.css?v=da010a1d2c900241','/board-worker.js?v=da010a1d2c900241','/optimizer-core.js?v=da010a1d2c900241','/engine.js?v=da010a1d2c900241','/cache-version.js?v=da010a1d2c900241','/ko.json?v=da010a1d2c900241','/logo.svg'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('stack-lab-assets-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>clients.claim())));
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==location.origin||url.pathname.startsWith('/api/')||url.pathname==='/ranking-catalog.json')return;if(request.mode==='navigate'){event.respondWith(fetch(request).then(response=>{if(response.ok){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(c=>c.put(request,copy)))}return response}).catch(()=>caches.match(request).then(r=>r||caches.match('/'))));return}event.respondWith(caches.open(CACHE).then(async cache=>{const saved=await cache.match(request);if(saved)return saved;const response=await fetch(request);if(response.ok)await cache.put(request,response.clone());return response}))});
